const _SUMMANDS: Record<string, [V, V][]> = {
  "a:giveUp": [[_match3, _fire3]],
  "a:retry": [[_match4, _fire4]],
  "a:start": [[_match5, _fire5]],
  "e:crashed": [[_match2, _fire2]],
  "e:finished": [[_match1, _fire1]],
  "e:submit": [[_match0, _fire0]],
};

/** Checks the action record against the unrefined Core (docs/spec.md §3.8.9). */
export class Acceptor {
  #s: V;

  constructor(config: Config) {
    this.#s = _initial(config);
  }

  /** Throws Rejected when no summand accepts the entry, Ambiguous when two do. */
  accept(entry: Entry): void {
    const [key, args] = "event" in entry
      ? ["e:" + entry.event.type, _args(entry.event, _EV)]
      : ["a:" + entry.action.type, _args(entry.action, _ACT)];
    const found: [V, V][] = [];
    for (const [match, fire] of _SUMMANDS[key] ?? []) {
      const env = match(this.#s, args);
      if (env !== null) found.push([fire, env]);
    }
    if (found.length === 0) throw new Rejected(entry);
    if (found.length > 1) throw new Ambiguous(entry);
    const s = { ...this.#s };
    found[0][0](s, found[0][1]);
    this.#s = s;
  }

  /** The acceptor's state. */
  get state(): State {
    return this.#s;
  }
}

// ---- the stepper of the refined Core (docs/spec.md §3.8)

function _ixmem_retryable(s: V, v: V): V {
  return ((s.st.get(v) === "FAILED") && (s.tries.get(v) < _m_retries()));
}

function _ixbound_retryable(s: V): V {
  return s.nj;
}

function _ixfirst_retryable(s: V): number {
  return s._ix_retryable.first(null);
}

function _ixsome_retryable(s: V): boolean {
  return s._ix_retryable.some(null);
}

function _ixrefresh_retryable(s: V, v: number): void {
  if (_ixmem_retryable(s, v)) s._ix_retryable.refresh(v, true, 0, 0);
  else s._ix_retryable.refresh(v, false, 0, 0);
}

function _ixmem_spent(s: V, v: V): V {
  return ((s.st.get(v) === "FAILED") && (s.tries.get(v) >= _m_retries()));
}

function _ixbound_spent(s: V): V {
  return s.nj;
}

function _ixfirst_spent(s: V): number {
  return s._ix_spent.first(null);
}

function _ixsome_spent(s: V): boolean {
  return s._ix_spent.some(null);
}

function _ixrefresh_spent(s: V, v: number): void {
  if (_ixmem_spent(s, v)) s._ix_spent.refresh(v, true, 0, 0);
  else s._ix_spent.refresh(v, false, 0, 0);
}

function _refresh(s: V): void {
  {
    const ids = new Set<number>(s._ix_retryable.ent.keys());
    for (let v = 0; v < _ixbound_retryable(s); v++) ids.add(v);
    for (const v of [...ids].sort((x, y) => x - y)) _ixrefresh_retryable(s, v);
  }
  {
    const ids = new Set<number>(s._ix_spent.ent.keys());
    for (let v = 0; v < _ixbound_spent(s); v++) ids.add(v);
    for (const v of [...ids].sort((x, y) => x - y)) _ixrefresh_spent(s, v);
  }
}

function _clone(s: V): V {
  const c = { ...s };
  c._ix_retryable = s._ix_retryable.clone();
  c._ix_spent = s._ix_spent.clone();
  return c;
}

function _stepper_init(s: V): void {
  s._ix_retryable = new _Index(3);
  s._ix_spent = new _Index(0);
  _refresh(s);
}

function _match_s0(s: V, a: V[]): V[] | null {
  // c_submit
  const v_j = a[0];
  if (!((v_j === s.nj))) return null;
  return [v_j];
}

function _fire_s0(s: V, env: V[]): void {
  const [v_j] = env;
  const _n_nj = _add(s.nj, 1);
  const _p_st: V[] = [];
  _p_st.push([0, v_j, "QUEUED"]);
  const _n_Q = _union(s.Q, _ins([], v_j));
  const _p_entered: V[] = [];
  _p_entered.push([0, "QUEUED", _add(s.entered.get("QUEUED"), 1)]);
  s.st = _run(s.st.clone(), _p_st);
  s.entered = _run(s.entered.clone(), _p_entered);
  s.nj = _fit(_n_nj, 0, 4294967295, "nj");
  s.Q = _n_Q;
}

function _match_s1(s: V, a: V[]): V[] | null {
  // c_finished
  const v_j = a[0];
  if (!((s.st.get(v_j) === "RUNNING"))) return null;
  return [v_j];
}

function _fire_s1(s: V, env: V[]): void {
  const [v_j] = env;
  const _p_st: V[] = [];
  _p_st.push([0, v_j, "DONE"]);
  const _n_slots = _add(s.slots, 1);
  const _p_entered: V[] = [];
  _p_entered.push([0, "DONE", _add(s.entered.get("DONE"), 1)]);
  s.st = _run(s.st.clone(), _p_st);
  s.entered = _run(s.entered.clone(), _p_entered);
  s.slots = _fit(_n_slots, 0, 4294967295, "slots");
}

function _match_s2(s: V, a: V[]): V[] | null {
  // c_crashed
  const v_j = a[0];
  if (!((s.st.get(v_j) === "RUNNING"))) return null;
  return [v_j];
}

function _fire_s2(s: V, env: V[]): void {
  const [v_j] = env;
  const _p_st: V[] = [];
  _p_st.push([0, v_j, "FAILED"]);
  const _n_slots = _add(s.slots, 1);
  const _p_entered: V[] = [];
  _p_entered.push([0, "FAILED", _add(s.entered.get("FAILED"), 1)]);
  s.st = _run(s.st.clone(), _p_st);
  s.entered = _run(s.entered.clone(), _p_entered);
  s.slots = _fit(_n_slots, 0, 4294967295, "slots");
}

function _out0(s: V, out: Action[]): boolean {
  // c_give_up
  if (!((_ixsome_spent(s) && ((s.st.get(_ixfirst_spent(s)) === "FAILED") && _m_spent(s.tries.get(_ixfirst_spent(s))))))) return false;
  out.push({ type: "giveUp", job: _ixfirst_spent(s) });
  const _p_st: V[] = [];
  _p_st.push([0, _ixfirst_spent(s), "GAVEUP"]);
  const _p_entered: V[] = [];
  _p_entered.push([0, "GAVEUP", _add(s.entered.get("GAVEUP"), 1)]);
  s.st = _run(s.st.clone(), _p_st);
  s.entered = _run(s.entered.clone(), _p_entered);
  return true;
}

function _out1(s: V, out: Action[]): boolean {
  // c_retry
  if (!((_ixsome_retryable(s) && ((s.st.get(_ixfirst_retryable(s)) === "FAILED") && (!_m_spent(s.tries.get(_ixfirst_retryable(s)))))))) return false;
  out.push({ type: "retry", job: _ixfirst_retryable(s) });
  const _p_st: V[] = [];
  _p_st.push([0, _ixfirst_retryable(s), "QUEUED"]);
  const _n_Q = _union(s.Q, _ins([], _ixfirst_retryable(s)));
  const _p_entered: V[] = [];
  _p_entered.push([0, "QUEUED", _add(s.entered.get("QUEUED"), 1)]);
  s.st = _run(s.st.clone(), _p_st);
  s.entered = _run(s.entered.clone(), _p_entered);
  s.Q = _n_Q;
  return true;
}

function _out2(s: V, out: Action[]): boolean {
  // c_start
  if (!((!_eq(s.Q, []) && (_has(s.Q, _least(s.Q)) && (s.slots > 0))))) return false;
  out.push({ type: "start", job: _least(s.Q) });
  const _p_st: V[] = [];
  _p_st.push([0, _least(s.Q), "RUNNING"]);
  const _p_tries: V[] = [];
  _p_tries.push([0, _least(s.Q), _add(s.tries.get(_least(s.Q)), 1)]);
  const _n_Q = _diff(s.Q, _ins([], _least(s.Q)));
  const _n_slots = _int2nat(_sub(s.slots, 1));
  const _p_entered: V[] = [];
  _p_entered.push([0, "RUNNING", _add(s.entered.get("RUNNING"), 1)]);
  const _p_byTries: V[] = [];
  _p_byTries.push([0, _add(s.tries.get(_least(s.Q)), 1), _add(s.byTries.get(_add(s.tries.get(_least(s.Q)), 1)), 1)]);
  s.st = _run(s.st.clone(), _p_st);
  s.tries = _run(s.tries.clone(), _p_tries);
  s.entered = _run(s.entered.clone(), _p_entered);
  s.byTries = _run(s.byTries.clone(), _p_byTries);
  s.Q = _n_Q;
  s.slots = _fit(_n_slots, 0, 4294967295, "slots");
  return true;
}

const _INS: [string, V, V][] = [
  ["submit", _match_s0, _fire_s0],
  ["finished", _match_s1, _fire_s1],
  ["crashed", _match_s2, _fire_s2],
];

const _OUTS = [_out0, _out1, _out2];

const _STEP: Record<string, [V, V][]> = {};
for (const [type, match, fire] of _INS) (_STEP[type] ??= []).push([match, fire]);

/** Every parameter's value, encoded as entries are: equal in every backend for equal states. */
export function stateBytes(state: State): Uint8Array {
  const s: V = state;
  const out: number[] = [];
  _enc(s.w, ["n"], out);
  _enc(s.nj, ["n"], out);
  _enc(s.st.d, ["e", ["FREE", "QUEUED", "RUNNING", "FAILED", "DONE", "GAVEUP"]], out);
  _enc(s.st.m.size, ["n"], out);
  for (const [k, v] of s.st.entries()) {
    _enc(k, ["n"], out);
    _enc(v, ["e", ["FREE", "QUEUED", "RUNNING", "FAILED", "DONE", "GAVEUP"]], out);
  }
  _enc(s.tries.d, ["n"], out);
  _enc(s.tries.m.size, ["n"], out);
  for (const [k, v] of s.tries.entries()) {
    _enc(k, ["n"], out);
    _enc(v, ["n"], out);
  }
  _enc(s.Q, ["l", ["n"]], out);
  _enc(s.slots, ["n"], out);
  _enc(s.entered.d, ["n"], out);
  _enc(s.entered.m.size, ["n"], out);
  for (const [k, v] of s.entered.entries()) {
    _enc(k, ["e", ["FREE", "QUEUED", "RUNNING", "FAILED", "DONE", "GAVEUP"]], out);
    _enc(v, ["n"], out);
  }
  _enc(s.byTries.d, ["n"], out);
  _enc(s.byTries.m.size, ["n"], out);
  for (const [k, v] of s.byTries.entries()) {
    _enc(k, ["n"], out);
    _enc(v, ["n"], out);
  }
  return Uint8Array.from(out);
}

/** A key equal for two states exactly when every step from them is the same: the parameters and
 * the order of the indexes that remember when an id entered (docs/spec.md §3.18.3). */
export function stateKey(state: State): string {
  const s: V = state;
  return [...stateBytes(state)].map((b) => b.toString(16).padStart(2, "0")).join("") + "|" + s._ix_retryable.ordered().join(",");
}

/** How an argument's values are enumerated when the state space is explored. */
export type Sort =
  | { readonly kind: "bool" }
  | { readonly kind: "int"; readonly sort: string }
  | { readonly kind: "id"; readonly sort: string; readonly ctor: string }
  | { readonly kind: "enum"; readonly sort: string; readonly values: readonly string[] }
  | { readonly kind: "other"; readonly sort: string };

export interface Arg {
  readonly name: string;
  readonly sort: Sort;
}

/** An input summand of the refined Core: the next state when it accepts the event, else null. */
export interface InputTransition {
  readonly summand: string;
  readonly label: string;
  readonly type: Event["type"];
  readonly args: readonly Arg[];
  next(state: State, event: Event): State | null;
}

/** An output summand of the refined Core, in policy order: the action and the next state when it is enabled. */
export interface OutputTransition {
  readonly summand: string;
  readonly label: string;
  readonly type: Action["type"];
  readonly args: readonly Arg[];
  next(state: State): { readonly state: State; readonly action: Action } | null;
}

/** The result of the constructor or of a step: the state and the actions taken, in order. */
export interface Step {
  readonly state: State;
  readonly actions: readonly Action[];
}

/** The input summands, in the model's order (docs/spec.md §3.18.3). */
export const inputs: readonly InputTransition[] = [
  {
    summand: "c_submit",
    label: "c_submit",
    type: "submit",
    args: [{ name: "job", sort: { kind: "id", sort: "Job", ctor: "job" } }],
    next(state: State, event: Event): State | null {
      const [type, match, fire] = _INS[0];
      if (event.type !== type) return null;
      const s = _clone(state);
      const env = match(s, _args(event, _EV));
      if (env === null) return null;
      fire(s, env);
      _refresh(s);
      return s;
    },
  },
  {
    summand: "c_finished",
    label: "c_finished",
    type: "finished",
    args: [{ name: "job", sort: { kind: "id", sort: "Job", ctor: "job" } }],
    next(state: State, event: Event): State | null {
      const [type, match, fire] = _INS[1];
      if (event.type !== type) return null;
      const s = _clone(state);
      const env = match(s, _args(event, _EV));
      if (env === null) return null;
      fire(s, env);
      _refresh(s);
      return s;
    },
  },
  {
    summand: "c_crashed",
    label: "c_crashed",
    type: "crashed",
    args: [{ name: "job", sort: { kind: "id", sort: "Job", ctor: "job" } }],
    next(state: State, event: Event): State | null {
      const [type, match, fire] = _INS[2];
      if (event.type !== type) return null;
      const s = _clone(state);
      const env = match(s, _args(event, _EV));
      if (env === null) return null;
      fire(s, env);
      _refresh(s);
      return s;
    },
  },
];

/** The output summands, in policy order: the first enabled one is taken (docs/spec.md §3.8.3). */
export const outputs: readonly OutputTransition[] = [
  {
    summand: "c_give_up",
    label: "c_give_up",
    type: "giveUp",
    args: [{ name: "job", sort: { kind: "id", sort: "Job", ctor: "job" } }],
    next(state: State) {
      const s = _clone(state);
      const out: Action[] = [];
      if (!_OUTS[0](s, out)) return null;
      _refresh(s);
      return { state: s, action: out[0] };
    },
  },
  {
    summand: "c_retry",
    label: "c_retry",
    type: "retry",
    args: [{ name: "job", sort: { kind: "id", sort: "Job", ctor: "job" } }],
    next(state: State) {
      const s = _clone(state);
      const out: Action[] = [];
      if (!_OUTS[1](s, out)) return null;
      _refresh(s);
      return { state: s, action: out[0] };
    },
  },
  {
    summand: "c_start",
    label: "c_start",
    type: "start",
    args: [{ name: "job", sort: { kind: "id", sort: "Job", ctor: "job" } }],
    next(state: State) {
      const s = _clone(state);
      const out: Action[] = [];
      if (!_OUTS[2](s, out)) return null;
      _refresh(s);
      return { state: s, action: out[0] };
    },
  },
];

function _loop(s: V, out: Action[]): void {
  // The output loop (docs/spec.md §3.8.3): the first enabled output in policy order, until none is.
  let n = 0;
  for (;;) {
    if (!_OUTS.some((f) => f(s, out))) return;
    _refresh(s);
    n += 1;
    if (n >= 2 ** 24) throw new StepLimit("2^24 actions in one step");
  }
}

/** The state s0 of docs/spec.md §3.8.1, before the constructor's output loop: where the transition table starts. */
export function start(config: Config): State {
  const s = _initial(config);
  _stepper_init(s);
  return s;
}

/** The initial state and the actions the constructor takes (docs/spec.md §3.8.1). */
export function initial(config: Config): Step {
  const s = _clone(start(config));
  const out: Action[] = [];
  _loop(s, out);
  return { state: s, actions: out };
}

/** Whether the event is accepted in the state (docs/spec.md §3.8.2). */
export function allowed(state: State, event: Event): boolean {
  return (_STEP[event.type] ?? []).some(([match]) => match(state, _args(event, _EV)) !== null);
}

/** Whether no output is enabled: the state every step ends in. */
export function quiescent(state: State): boolean {
  return outputs.every((t) => t.next(state) === null);
}

/** The step (docs/spec.md §3.8.2): the next state and the actions, or null when the event is refused,
 * which changes nothing. Any other error is a StepError and ends the run (docs/spec.md §3.8.5). */
export function step(state: State, event: Event): Step | null {
  const s = _clone(state);
  const args = _args(event, _EV);
  for (const [match, fire] of _STEP[event.type] ?? []) {
    const env = match(s, args);
    if (env !== null) {
      fire(s, env);
      _refresh(s);
      const out: Action[] = [];
      _loop(s, out);
      return { state: s, actions: out };
    }
  }
  return null;
}
